<script setup lang="ts">
import { onMounted,ref } from 'vue';import { ElMessage,ElMessageBox } from 'element-plus';import { inventoryApi } from '@/api'
const batches=ref<any[]>([]),ledger=ref<any[]>([]);const load=async()=>{[batches.value,ledger.value]=await Promise.all([inventoryApi.batches(),inventoryApi.ledger()])};onMounted(load)
const adjust=async(row:any)=>{const {value:type}=await ElMessageBox.prompt('INCREMENT 增加 / DECREMENT 减少 / SET 设定','调整批次库存',{inputValue:'INCREMENT',inputValidator:v=>['INCREMENT','DECREMENT','SET'].includes(v.toUpperCase())||'请输入有效类型'});const {value:quantity}=await ElMessageBox.prompt('请输入非负整数数量','调整批次库存',{inputValue:'1',inputValidator:v=>/^\d+$/.test(v)||'请输入非负整数'});const {value:reason}=await ElMessageBox.prompt('必须填写可审计的调整原因','调整批次库存',{inputValidator:v=>!!v.trim()||'原因不能为空'});await inventoryApi.adjust(row.id,{adjustType:type.toUpperCase(),quantity:Number(quantity),reason});ElMessage.success('批次库存与库存台账已同步更新');await load()}
</script>
<template><div class="workbench"><h1>批次库存工作台</h1><p>按失效日期查看批次与不可变库存流水；隔离、过期批次永不参与销售。</p><h2>批次</h2><el-table :data="batches"><el-table-column prop="batchNo" label="批号"/><el-table-column prop="medicineId" label="药品 ID"/><el-table-column prop="expiryDate" label="失效日期"/><el-table-column prop="availableQty" label="可用"/><el-table-column prop="reservedQty" label="预占"/><el-table-column prop="qualityStatus" label="质量状态"/><el-table-column label="操作"><template #default="{row}"><el-button type="warning" plain @click="adjust(row)">盘盈 / 盘亏</el-button></template></el-table-column></el-table><h2>最近流水</h2><el-table :data="ledger"><el-table-column prop="eventNo" label="事件号"/><el-table-column prop="businessType" label="业务"/><el-table-column prop="batchId" label="批次 ID"/><el-table-column prop="availableDelta" label="可用变化"/><el-table-column prop="reservedDelta" label="预占变化"/><el-table-column prop="createTime" label="时间"/></el-table></div></template>
<style scoped>.workbench{max-width:1200px;margin:40px auto;padding:24px;background:#fff;border-radius:16px}.workbench>p{color:#718198}.workbench h2{margin-top:28px}</style>
